function entry(slug, title, summary, ...sections) {
  return {slug, title, summary, sections: sections.map(([heading, ...paragraphs]) => ({heading, paragraphs}))};
}

const concepts = [
  entry('affordances', 'Affordances', 'How the shape and placement of an object tell players what they can do with it.',
    ['Make the action plausible', 'A rail affords sliding if the movement system supports it. Its height, uninterrupted length and position near a landing can help players recognise that possibility. Readability depends on what the character can actually do in the space.'],
    ['Check neighbouring objects', 'Put the usable rail beside one that only marks an edge. Watch a player approach both at speed. If the objects look interchangeable, change the silhouette, approach or response so the distinction holds throughout the level.']),
  entry('large-medium-small', 'Large, Medium and Small Shapes', 'Establish a clear silhouette before adding structure and detail.',
    ['Assign each scale a job', 'Large shapes set the silhouette. Medium shapes show how parts fit together. Small shapes add material and wear cues. Give the main mass room to read, with small details concentrated around joints, edges or areas of interest.'],
    ['Review at gameplay distance', 'Thumbnail the design and blur it. If every section carries the same weight, combine some medium shapes or move detail into clusters. A deliberate imbalance can help one mass lead while others support it.']),
  entry('cel-shading', 'Cel Shading', 'Use lighting bands and deliberate edges to give 3D forms a drawn appearance.',
    ['Build a readable lighting ramp', 'Cel shading maps lighting to a few distinct tones. Decide how many steps the form needs and where the light changes from one band to the next. Outlines can help separate overlapping surfaces.'],
    ['Test motion as well as stills', 'Check the character against environments of different values. Turn the model under a moving light and look for bands or outlines that flicker. Adjust the lighting thresholds or edge handling before expanding the style to more assets.']),
  entry('collision-detection', 'Collision Detection', 'Match contact shapes and game responses to what the player sees.',
    ['Separate checking contact from responding', 'A game can detect whether shapes overlap or whether a moving shape crosses a surface. The result might block movement, start a trigger or report a hit. Give each object the collision behaviour its role requires.'],
    ['Test proxy shapes in context', 'Use simple shapes where they approximate the playable surface. Move through a doorway, along adjacent props and toward thin geometry at full speed. Watch for snagging, invisible barriers and fast movement that skips a contact.']),
  entry('cover', 'Cover in Games', 'Make shelter and exposure clear enough to support movement decisions.',
    ['Give protection a visible shape', 'Height and direction tell the player what a piece of cover offers. A low barrier can preserve visibility while exposing more of the character. Solid cover can support a safe pause and a change of route.'],
    ['Keep the encounter moving', 'Check whether the safest position dominates an entire encounter. Give the player a reason to move, such as a different view or an objective they can reach from another position. Signal when destructible cover is about to stop protecting them.']),
  entry('destructible-environments', 'Destructible Environments', 'Treat damaged scenery as a change in the playable level.',
    ['Define what destruction changes', 'A breakable partition can open a path or expose a room. Agree on which parts break and which connections stay available. Use cracks, material or a staged reaction to make breakable objects recognisable.'],
    ['Test the altered layout', 'Play before and after breaking the object. Check collision, navigation, sightlines and whether debris hides an important cue. Put a budget on fragments and persistent effects so busy scenes remain playable.']),
  entry('diegetic-ui', 'Diegetic UI', 'Show information through objects that belong to the game world.',
    ['Tie the display to an object', 'A gauge on a vehicle or a status light on equipment can communicate a game state inside the fiction. Put the cue where the player naturally looks at the moment they need it.'],
    ['Test reading under pressure', 'Check the display in motion, in low light and at different camera distances. Repeat critical information in another accessible form when the in-world display can be obscured or colour alone is hard to read.']),
  entry('character-part-damage', 'Character Part Damage', 'Use local damage states to communicate changes in a fictional encounter.',
    ['Make the change affect the encounter', 'A creature losing an armoured appendage can change its movement, attack choices or vulnerable areas. Give the player a clear signal about which behaviour changed and when.'],
    ['Limit the states you have to support', 'Each visible state needs compatible animation, collision and effects. Prototype one break point with a clean transition and a readable aftermath before giving every part its own state.']),
  entry('dynamic-difficulty', 'Dynamic Difficulty', 'Adjust challenge in response to play while keeping the rules predictable.',
    ['Watch a pattern of play', 'Repeated failures, long stalls and ample resources can each suggest different problems. Use several observations and leave time between adjustments so a single mistake does not trigger a change.'],
    ['Adjust the margin', 'Try a longer recovery window or a more accessible resource. Keep the relationship between the player action and its outcome intact. Playtest whether a struggling player sees a new way forward and whether improving still feels earned.']),
  entry('storytelling-through-spaces', 'Storytelling Through Spaces', 'Place clues that reveal what happened and prepare players for what comes next.',
    ['Leave traces where the event happened', 'An empty service desk, a barricade and a dropped bag can suggest an evacuation. Use placement and wear to show what occurred first and which detail a hurried visitor might miss.'],
    ['Let the story help the player act', 'A damaged object beside a new hazard can warn of its effect. A convincing path of clues can also teach where to look or how to approach a space. Ask a tester what they inferred before giving them dialogue or a prompt.']),
  entry('framing', 'Framing', 'Use sightlines and composition to put important information where players can see it.',
    ['Choose the likely point of view', 'Doorframes, skylines and negative space can pull attention toward a destination. Check the composition from the approach, camera height and field of view players are likely to use.'],
    ['Plan variation in movement', 'An important clue may disappear if the player turns early or takes another route. Use a secondary cue or another angle. Test the reveal while someone moves freely at gameplay speed.']),
  entry('game-design', 'Game Design', 'Connect rules, encounters and levels to the experience you want players to have.',
    ['Start with a player decision', 'Describe what the player notices, what options they have and how the game responds. A systems designer develops reusable rules. A content or level designer gives those rules situations where decisions matter.'],
    ['Check where disciplines meet', 'Write down how a rule appears in a scene and how the player learns it. A combat adjustment might change the space an encounter needs, so review the rule and the room together.']),
  entry('inverse-kinematics', 'Inverse Kinematics', 'Place a foot, hand or other endpoint at a target while keeping the pose believable.',
    ['Solve from the contact point', 'Inverse kinematics works backward from a target such as a foot on a step. The solver adjusts the joints in the chain so the endpoint can meet that target. Apply limits to keep the pose within the character’s usable range.'],
    ['Blend with authored motion', 'Keep the timing and intent of the animation. Gradually adjust the pose as contact begins and ends, and test sloped or moving surfaces for foot sliding and abrupt joint changes.']),
  entry('landmarks', 'Landmarks', 'Give players distinctive reference points they can recognise from several routes.',
    ['Choose a navigational role', 'A tall tower might orient the player across a district. A painted doorway might mark a decision near the destination. Give the landmark a recognisable silhouette or colour at the distance where it needs to work.'],
    ['Test visibility over a route', 'Observe where the landmark first becomes visible, disappears and returns. A lit intersection or a change in street layout can guide the player while the distant landmark is out of sight.']),
  entry('level-streaming', 'Level Streaming', 'Load and release parts of a world as the player moves through it.',
    ['Plan transitions around movement', 'Split a world into chunks and request likely destinations early enough to make them playable. Unload distant content to free memory. Traversal routes and sightlines affect how much lead time the system has.'],
    ['Test the worst route', 'Try fast travel, rapid turns and backtracking near a boundary. Check for frame spikes and late collision or lighting. Extend overlap where load time varies, and prioritise assets the player may need to see or use immediately.']),
  entry('photobashing', 'Photobashing', 'Blend photographic elements into concept art while keeping lighting and perspective coherent.',
    ['Use photographs for a specific job', 'A photo can give a surface believable texture or help resolve a complex shape. Establish the silhouette, light direction and major values first so the photographs support the design.'],
    ['Paint the joins', 'Match scale, perspective and colour before blending. Repaint boundaries and simplify noisy detail so the final image has the same logic throughout. Check the design at thumbnail size and keep track of image rights.']),
  entry('ragdoll-physics', 'Ragdoll Physics', 'Let a character respond to the environment through a simulated body.',
    ['Hand off cleanly', 'Start the simulation from the current pose and movement so the change is readable. Joint limits and simple collision shapes help prevent the model from folding into implausible positions.'],
    ['Check the gameplay consequences', 'Test tight corners, stairs and multiple nearby characters. Decide whether a resting model can obstruct movement and when simulation can stop. The reactions should stay readable and affordable during busy scenes.']),
  entry('signifiers', 'Signifiers', 'Communicate where and how a player can perform an action.',
    ['Pair the cue with an action', 'A handle makes something look graspable. An icon, light or familiar marking can tell the player which handle operates a lift. Put the cue near the point of action and repeat it under the same conditions elsewhere.'],
    ['Avoid contradictory cues', 'If a marker sometimes means an object is usable and sometimes serves as decoration, players have to guess. Watch whether first-time players notice the cue and act on it without a prompt.']),
  entry('three-phases-of-animation', 'Anticipation, Contact and Recovery', 'Structure action animation around the cue, the active moment and the return of control.',
    ['Give every phase a purpose', 'Anticipation communicates what is about to happen. Contact gives the action its gameplay effect. Recovery indicates when the character can act again. Align gameplay timing and visual feedback across the three phases.'],
    ['Review the timing in play', 'Use the action at different speeds and distances. Make sure a compressed anticipation remains readable and a long recovery produces a meaningful commitment. Test interruption and transitions back to movement.']),
  entry('vsync', 'Vertical Synchronisation', 'Understand the trade-offs between tearing, pacing and input response.',
    ['Coordinate the frame and the display', 'A tear can appear when the display starts showing a newer frame partway through scanning the current one. Vertical synchronisation coordinates presentation with the refresh cycle. Buffering and variable refresh can change the result.'],
    ['Measure the complete experience', 'Compare frame pacing and input response with the actual display modes the game supports. Watch what happens when rendering falls below the refresh rate, and describe the trade-off clearly in the settings.']),
  entry('wall-running', 'Wall Running', 'Design wall routes around readable surfaces and reliable exits.',
    ['Teach the surface in a safe space', 'Give runnable walls a consistent silhouette, material or seam. Let the player learn how to enter and leave the run in a short gap with an obvious landing.'],
    ['Make the exit visible during motion', 'Connect the wall run to another surface or a meaningful choice. Play the route with different approach speeds and camera angles. Check where the player looks just before leaving the wall.'])
];

const levelArt = [
  entry('level-art-basics', 'Level Art Basics', 'Understand how art communicates the purpose, structure and history of a game level.',
    ['Start with the player’s objective', 'A level gives the player a place to act and a reason to move through it. The design defines routes, challenges and decisions. Level art turns those spaces into a coherent world and makes the important parts easy to read.'],
    ['Build a visual vocabulary', 'Agree how the level signals access, danger and points of interest. Carry those rules across materials, shapes and lighting. Take a first-time player through a room and check what they infer from the art alone.']),
  entry('level-design-basics', 'Level Design Basics', 'Read a blockout, a beat sheet and the gameplay measurements that guide a level.',
    ['Measure the blockout', 'Check the move set, camera and collision before refining geometry. A doorway that fits the character may still obstruct the camera. A platform that looks close may sit outside the jump range. Record the measurements designers and artists need to share.'],
    ['Connect space to pacing', 'Use the beat sheet to understand what the player does in each area. Give the geometry room for that action, and review the route at normal speed before replacing basic shapes with final meshes.']),
  entry('level-visual-storytelling', 'Visual Storytelling in Levels', 'Turn worldbuilding into clues players can encounter along a route.',
    ['Work from the world to the room', 'Decide who built the space, how it was used and what happened recently. Then choose objects and traces that make those details visible. A reinforced doorway and a worn alternate path can suggest changes in how people move through the building.'],
    ['Choose which information matters to play', 'Place the clue that explains the route where it can be seen while moving. Reserve notes, small objects and optional corners for extra detail. Ask testers what they understood and which clue led them there.']),
  entry('level-visual-composition', 'Visual Composition in 3D Levels', 'Guide attention through contrast, sightlines and space around the focal point.',
    ['Compose for a moving camera', 'Review the sightline from each likely entrance. Use value contrast and a distinct silhouette to make a destination stand out. Repeated forms and directional lines can support the route across the rest of the scene.'],
    ['Give important shapes room', 'Clear nearby clutter if it competes with the objective. Compare shots from different heights and distances, then walk the route at speed to check that the focal point remains readable.']),
  entry('level-art-pipeline', 'The Level Art Pipeline', 'Move from visual targets and modular kits to playable, polished levels.',
    ['Prove the target in a small area', 'Turn the creative brief into a reference set, an asset kit and a scene that demonstrates the intended quality. Review a beautiful corner for presentation and a playable slice for production feasibility.'],
    ['Build with the dependencies visible', 'Schedule reusable assets before the rooms that rely on them. Record who owns layout, collision, lighting and final checks. Test representative scenes on target hardware during production so expensive changes can happen before polish.']),
  entry('art-design-collaboration', 'How Art and Design Collaborate', 'Keep gameplay intent and visual development aligned from blockout to polish.',
    ['Review the brief together', 'List the routes, interactions and story beats that the scene has to support. Identify geometry the art pass can change freely and areas that need a joint review, such as ledges, cover, camera space and scripted events.'],
    ['Review the actual build', 'At each handoff, walk through the intended route together. Check whether the new art changes the distance, shape or readability of an important action. Record the decision, the build and who needs to verify it.']),
  entry('level-navigation-aids', 'Environmental Navigation Aids', 'Help players pick out routes and usable objects without filling the view with markers.',
    ['Give cues consistent meanings', 'Use landmarks for orientation and smaller cues at local decisions. A line of lights can invite movement. A repeated edge treatment can tell players where a climb is possible. Keep decorative elements from copying those signals by accident.'],
    ['Watch a player take a wrong turn', 'At each junction, ask which route looked viable and why. Improve the view, framing or affordance before adding more markers. Offer another way to read information that would otherwise rely on colour alone.']),
  entry('level-art-optimization', 'Level Art Optimization', 'Measure where a scene spends frame time and memory before changing its art.',
    ['Set a target and gather evidence', 'Capture frame time and memory in representative scenes on target hardware. Separate rendering cost, game-thread work and streaming before choosing an optimization. Record the camera position and traversal path so the test can be repeated.'],
    ['Protect the things players notice', 'Review draw distance, material complexity, lighting and dense props. Simplify work that contributes little at the normal viewing distance. Play the same route after the change and compare both measurements and visual readability.']),
  entry('level-artist-field-guide', 'Level Artist Field Guide', 'Use concept art, architecture and real-world references to make playable spaces feel coherent.',
    ['Translate the sketch into playable space', 'Identify what the concept establishes about scale, materials and the focal point. Build a rough mock-up and bring the player camera through it. Use real structures to check how stairs, supports, entrances and circulation fit together.'],
    ['Check the world at ground level', 'Walk from the primary route to a side entrance. See whether building details suggest a believable use and whether the player can still pick out the objective. Keep the features that support the location’s identity and gameplay.'])
];

const graphicsPipeline = [
  entry('graphics-fundamentals', 'Real-Time Graphics Fundamentals', 'Understand the decisions behind a frame the game must produce while the player acts.',
    ['Different work for different shots', 'A pre-rendered scene can spend more time calculating lighting and effects. A game frame is produced repeatedly while the camera and simulation change. Spend the available time on details players can perceive during play.'],
    ['Budget for the busiest view', 'Compare a calm room with a fast, effect-heavy encounter. Look at frame time and memory while moving through both. Choose a visual target that represents the work the game can sustain.']),
  entry('constructing-3d-graphics', 'From 3D Assets to Pixels', 'Follow geometry, materials and lighting from the asset to the final image.',
    ['Start with what the asset supplies', 'Vertices and triangles describe the surface. Attributes such as texture coordinates and normals help shaders decide what the surface should look like. The camera determines where the geometry appears on screen.'],
    ['Track where the appearance comes from', 'After geometry is projected, the graphics pipeline works out which screen samples a triangle covers. Materials and lighting determine their appearance. Use this chain to diagnose whether a visual fault starts in the mesh, material, lighting or display output.']),
  entry('console-anatomy', 'How Console Hardware Builds a Frame', 'Understand the roles of storage, memory, processors and display output.',
    ['Follow the data', 'Storage holds assets until the game needs them. Memory holds active resources. The CPU advances gameplay and submits rendering work, while the GPU processes commands and produces the image. These stages can overlap from one frame to the next.'],
    ['Separate processing from transfer cost', 'A slow frame may come from game logic, GPU work or assets arriving late. Measure the stages separately. Inspect memory use as well as speed, since a scene can render quickly and still strain the system during a transition.']),
  entry('gpu-pipeline', 'The GPU Pipeline', 'Follow vertices through projection, rasterisation and shading.',
    ['Move geometry into view', 'The vertex stage transforms object positions for the camera. Rasterisation determines which screen samples those triangles cover. Fragment or pixel shaders evaluate materials and lighting for those samples. Depth and blending decisions determine what reaches the image.'],
    ['Diagnose the expensive stage', 'Compare the cost of more objects, more geometry and more pixels. Lower resolution during a test and see whether much of the cost goes away. Use the result to choose where to profile next.']),
  entry('rendering-optimization', 'Rendering Optimization', 'Choose rendering changes that address the measured bottleneck.',
    ['Measure before changing assets', 'Capture a repeatable view and inspect frame time. Geometry, shader work, transparency and lighting can all contribute. A material change will have limited effect if the scene is spending most of its time elsewhere.'],
    ['Change one cost and compare', 'Try a lower detail mesh at distance, fewer layered surfaces, or a simpler shader where the difference is hard to see. Record the performance gain and check the image in motion. Keep changes that improve the actual gameplay view.'])
];

const shapeLanguage = [
  entry('shape-language-fundamentals', 'Shape Language Fundamentals', 'Use silhouettes, proportions and motion to communicate through characters, environments and effects.',
    ['Start with large shapes', 'Round, angular and blocky masses create different impressions through rhythm and balance. Treat these as design tendencies and test them in context. A low triangular silhouette can read differently from a tall one made of the same pieces.'],
    ['Apply the vocabulary to characters and spaces', 'Give a character a recognisable silhouette and use secondary shapes to explain its structure or role. In environments, repeat shapes where spaces belong together and vary them near a focal point or route transition.'],
    ['Carry it into composition and effects', 'An effect can borrow the shape vocabulary of the action or object that produces it. Check that its silhouette stays readable against the environment. Review thumbnails and short clips to see which shapes still communicate at play speed.'])
];

const caseStudies = [
  entry('technical-art-for-live-characters', 'Technical Art for Live Character Production', 'How pipeline support helps a character team keep producing assets while its tools and infrastructure change.',
    ['The production problem', 'A live character pipeline depends on artists exporting assets that pass engine constraints and match an established visual style. Small failures in version control, export or review can interrupt several disciplines at once.'],
    ['Build checks into the handoff', 'The team paired daily troubleshooting with documented export checks and a quality tool integrated into the workflow. A phased version-control move let a smaller group test the new setup before the whole production team switched. The pattern is to catch predictable failures early while keeping an escalation path for new ones.']),
  entry('recovering-an-environment-delivery', 'Recovering an Environment Art Delivery', 'How a team rebuilt confidence after an early environment-art delivery missed the quality bar.',
    ['Find the actual gaps', 'The team was handling unfamiliar runtime constraints alongside buildings, props and vegetation. It made progress by identifying the skills and checks missing from the initial delivery. That gave it recurring problems to address across assets.'],
    ['Rehearse, train and review', 'Targeted coaching addressed individual gaps. Shared examples made the new checks easier to teach. Reviewing work in layers before submission kept technical and visual checks from depending on one person just before delivery.']),
  entry('shared-documentation-for-character-production', 'Shared Documentation for Character Production', 'How a shared workspace can reduce time spent chasing the latest brief, file or approval.',
    ['The information problem', 'Several disciplines were relying on email to exchange specifications and assets. An update might reach one group without reaching the next. Repeat questions were a sign that the current answer was hard to find.'],
    ['Build the page around the handoff', 'The team kept active specifications, references and review steps together. A consistent hierarchy made important information visible first, with detailed instructions available as needed. A current page and a separate notification give people both a place to check and a reason to look.']),
  entry('designing-creatures-in-pairs', 'Designing Creatures in Pairs', 'How concept and 3D artists can develop a creature together from early silhouettes to final presentation.',
    ['Define the creature’s logic', 'The exercise paired concept work with 3D development within a shared brief. Ideas became easier to compare once the team specified scale, habitat and movement. Forms could then be judged by the behaviour they suggested.'],
    ['Use a rough model to test the idea', 'A cheap 3D study exposes awkward joints, weak silhouettes and camera angles that a single drawing can hide. Bring those findings back into the sketch. Use texture and presentation after the creature’s structure holds up from several views.']),
  entry('a-technical-art-support-playbook', 'A Technical Art Support Playbook', 'Turn recurring support questions into a practical guide for new artists.',
    ['Write for the person who gets stuck', 'The team was repeatedly answering similar questions about authoring and optimization. It started with the problems newer artists encountered most often and explained why each step mattered. That made the guide easier to use when the immediate symptom looked a little different.'],
    ['Make the guide easy to maintain', 'Pair an explanation with a clear demonstration of the expected result. Give someone responsibility for updating it when new questions recur. Cover common paths first and let specialists handle complex exceptions.']),
  entry('shared-art-direction-in-co-development', 'Shared Art Direction in Co-development', 'How an external team can turn open questions and feedback into a shared visual standard.',
    ['Put unanswered decisions in one place', 'A new project needed working agreements on materials, lighting and review conditions. The team gathered questions together so stakeholders could resolve dependencies in context. It used early experiments to clarify which decisions actually needed input.'],
    ['Make the approved result reproducible', 'A style guide can record the target image, the setup that produced it and the constraints that matter in game. Use a standard review scene and fold recurring feedback into the guide, so later artists can reproduce the decision.']),
  entry('handling-two-review-paths', 'Handling Two Review Paths', 'Keep work moving when an asset has to satisfy two groups with different approval criteria.',
    ['Find where the criteria differ', 'In a multi-party review, one group may focus on visual execution while another checks gameplay fit or consistency with an established world. Map who decides each question and when the feedback is expected.'],
    ['Turn feedback into checks', 'Sort recurring notes by issue and review phase. Apply the agreed checks to the next asset, then surface any genuine disagreement early. A producer can track the time spent waiting for decisions alongside the time spent making changes.']),
  entry('consistent-quality-for-complex-creatures', 'Consistent Quality for Complex Creatures', 'How a team used mentoring, benchmarks and review routines to align a complex character pipeline.',
    ['Set the quality bar where everyone can see it', 'Large creatures combined organic shapes with mechanical components. The team broke the work into smaller pieces and used benchmark examples to make the expected result easier to compare.'],
    ['Give review a regular rhythm', 'Mentoring helped newer artists learn both the techniques and the reasons for using them. Frequent reviews exposed deviations early. Quality checks at the assembly stage confirmed that individually acceptable parts still worked together.']),
  entry('keeping-vr-levels-consistent', 'Keeping VR Levels Consistent', 'Maintain a shared standard when several teams build environments for a VR game.',
    ['Agree on checks that transfer between levels', 'Asset-level experience did not cover every problem in a complete VR environment. The teams had to establish how scale, interaction, comfort and rendering budgets would be checked across the finished level.'],
    ['Share the fixes that travel', 'A common review process made it easier to bring questions and discoveries from one team to another. Test a reusable fix in more than one level before putting it into the standard. Keep reference decisions attached to the environment they affect.']),
  entry('preparing-teams-for-vr-production', 'Preparing Teams for VR Production', 'Reduce late rework by validating risky requirements early and teaching the findings through practice.',
    ['Prototype the technical unknowns', 'A dedicated group can test expensive level concepts and performance limits before the full team builds content. Choose a representative scene, measure it on target hardware and record what the team can realistically repeat.'],
    ['Teach the workflow after it is proven', 'Short demonstrations help explain workflows that are easier to see than read. A small practice task then shows whether the lesson transferred. Use recurring mistakes to improve the guide and the production checks.']),
  entry('testing-rendering-and-world-tools', 'Testing Rendering and World Tools', 'Evaluate new lighting, geometry, shadows and streaming features against a real production target.',
    ['Test the claims individually', 'A technology preview explored dynamic indirect lighting, virtualised geometry, cached shadow detail and cell-based streaming. Each feature solves a different problem and has different failure modes. Establish a small test for each before combining them.'],
    ['Repeat with representative content', 'Compare the result with a known baseline and test moving lights, busy views, repeated props and traversal across cell boundaries. Record the build and conditions for every finding. A technology choice should follow the game’s needs and measured behaviour on its target hardware.'])
];

export const libraryCollections = {
  concept: {title: 'Concept', groups: [{entries: concepts}]},
  'brain-snacks': {title: 'Brain Snacks', groups: [
    {title: 'Level Art Fundamentals', entries: levelArt},
    {title: '3D Graphic Pipelines', entries: graphicsPipeline},
    {title: 'Shape Language Fundamentals', entries: shapeLanguage}
  ]},
  'case-study': {title: 'Case Study', groups: [{entries: caseStudies}]}
};
